def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return min(budget, 20.0)

    yesterday_bids = []
    fixed_70_present = False
    desperate_opp = 0
    high_pressure = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = None
        if prev:
            pbid = prev.get('bid')
        if pbid is not None:
            yesterday_bids.append(float(pbid))
            if abs(float(pbid) - 70.0) < 1e-9:
                fixed_70_present = True
            if float(pbid) >= 90.0:
                high_pressure += 1
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            desperate_opp += 1

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    pressure = 0
    if slots <= 1:
        pressure += 3
    elif slots == 2:
        pressure += 1
    pressure += min(desperate_opp, 2)
    if fixed_70_present:
        pressure += 1
    if high_pressure >= 2:
        pressure += 1

    target = 32.0
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev >= 100.0:
            target = 71.0 if urgency + pressure >= 4 else 28.0
        elif max_prev >= 70.0:
            target = 71.0 if urgency + pressure >= 3 else 35.0
        else:
            target = min(72.0, max_prev + 3.0)
    else:
        target = 40.0

    if slots >= 2 and urgency <= 1:
        target = min(target, 34.0)
    if slots <= 1 and (urgency >= 2 or pressure >= 4):
        target = max(target, 71.0)
    if hp <= 2 or no_water_days >= 2:
        target = max(target, 72.0)
    if hp <= 1:
        target = max(target, 90.0)

    remaining_days = max(1, 10 - int(day) + 1)
    reserve_floor = max(0.0, (remaining_days - 1) * 12.0)
    affordable = max(0.0, budget - reserve_floor)
    if urgency >= 3:
        affordable = budget

    bid = min(target, affordable if affordable > 0 else budget)
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 85.0

    if my_status['hp'] <= 5:
        bid = min(my_status['budget'], avg_opp_bid * 1.15)
    else:
        bid = min(my_status['budget'], avg_opp_bid * 0.95)

    return float(max(10.0, min(bid, DAILY_SALARY * 1.2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']
    alive_opp = {k:v for k,v in opponents_status.items() if v['alive']}
    if not alive_opp:
        return min(budget, SALARY * 0.4)
    prev_bids = []
    for opp in alive_opp.values():
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    if prev_bids:
        highest_prev = max(prev_bids)
        target = highest_prev + 1.5
    else:
        target = SALARY * 0.6
    if hp <= 2 or no_water > 0:
        base = max(target, SALARY * 0.8)
        max_bid = min(budget, SALARY * 1.0)
    else:
        base = target
        max_bid = min(budget, SALARY * 0.85)
    bid = min(budget, base)
    bid = min(bid, max_bid)
    if supply < 18:
        bid = max(bid, SALARY * 0.7)
    return float(min(bid, budget))
